import{_ as a,o as i,c as t,ao as r}from"./chunks/framework.DdhParCf.js";const d=JSON.parse('{"title":"Examples","description":"","frontmatter":{},"headers":[],"relativePath":"examples.md","filePath":"examples.md","lastUpdated":null}'),n={name:"examples.md"};function s(p,e,o,l,c,h){return i(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="Examples" tabindex="-1">Examples <a class="header-anchor" href="#Examples" aria-label="Permalink to &quot;Examples {#Examples}&quot;">​</a></h1><p>These recipes cover complete device models. Start with the <a href="./quickstart">quickstart</a> if you want a small first calculation. Each page lists its dependencies and what to inspect in the output.</p><p>The original section headings below remain as links so existing bookmarks continue to identify the corresponding example.</p><h2 id="Josephson-parametric-amplifier-JPA" tabindex="-1">Josephson parametric amplifier (JPA) <a class="header-anchor" href="#Josephson-parametric-amplifier-JPA" aria-label="Permalink to &quot;Josephson parametric amplifier (JPA) {#Josephson-parametric-amplifier-JPA}&quot;">​</a></h2><p><a href="./recipes/jpa">Josephson parametric amplifier (JPA)</a>. Calculate reflection gain near the resonance of a current-pumped JPA, then compare with WRspice. The signal-frequency sweep uses the small-signal response about the strong pump. Refine both harmonic limits before interpreting the peak gain.</p><h2 id="JPA-with-a-frequency-dependent-environmental-impedance" tabindex="-1">JPA with a frequency dependent environmental impedance <a class="header-anchor" href="#JPA-with-a-frequency-dependent-environmental-impedance" aria-label="Permalink to &quot;JPA with a frequency dependent environmental impedance {#JPA-with-a-frequency-dependent-environmental-impedance}&quot;">​</a></h2><p><a href="./recipes/environment">JPA with a frequency dependent environmental impedance</a>. Compare the same JPA with a matched environment and a mismatched cable. This example changes the pump loading as well as the signal response; it is not just a phase correction to the output.</p><h2 id="Double-pumped-Josephson-parametric-amplifier-JPA" tabindex="-1">Double-pumped Josephson parametric amplifier (JPA) <a class="header-anchor" href="#Double-pumped-Josephson-parametric-amplifier-JPA" aria-label="Permalink to &quot;Double-pumped Josephson parametric amplifier (JPA) {#Double-pumped-Josephson-parametric-amplifier-JPA}&quot;">​</a></h2><p><a href="./recipes/double-pump">Double-pumped Josephson parametric amplifier (JPA)</a>. Drive the JPA with two independent strong tones and inspect the response between them. Each pump adds a Fourier-grid dimension, so refine the harmonic limits while watching memory use.</p><h2 id="Flux-pumped-Josephson-parametric-amplifier-JPA" tabindex="-1">Flux-pumped Josephson parametric amplifier (JPA) <a class="header-anchor" href="#Flux-pumped-Josephson-parametric-amplifier-JPA" aria-label="Permalink to &quot;Flux-pumped Josephson parametric amplifier (JPA) {#Flux-pumped-Josephson-parametric-amplifier-JPA}&quot;">​</a></h2><p><a href="./recipes/flux-pump">Flux-pumped Josephson parametric amplifier (JPA)</a>. Bias a SQUID through a mutual inductor and apply a pump near twice its resonance. The DC and three-wave-mixing options retain the modes needed by the flux bias and pump. The final sweep maps the pump-off resonance against bias.</p><h2 id="SNAIL-Parametric-Amplifier" tabindex="-1">SNAIL Parametric Amplifier <a class="header-anchor" href="#SNAIL-Parametric-Amplifier" aria-label="Permalink to &quot;SNAIL Parametric Amplifier {#SNAIL-Parametric-Amplifier}&quot;">​</a></h2><p><a href="./recipes/snail">SNAIL Parametric Amplifier</a>. Compare pump-on and pump-off gain for an explicitly modeled SNAIL. The quadratic nonlinearity supports three-wave mixing. Similar resonance frequencies in the two curves indicate operation near the chosen Kerr-free point.</p><h2 id="Josephson-traveling-wave-parametric-amplifier-JTWPA" tabindex="-1">Josephson traveling wave parametric amplifier (JTWPA) <a class="header-anchor" href="#Josephson-traveling-wave-parametric-amplifier-JTWPA" aria-label="Permalink to &quot;Josephson traveling wave parametric amplifier (JTWPA) {#Josephson-traveling-wave-parametric-amplifier-JTWPA}&quot;">​</a></h2><p><a href="./recipes/traveling-wave">Josephson traveling wave parametric amplifier (JTWPA)</a>. Build a resonant-phase-matched JTWPA from repeated cells. Inspect forward and reverse gain, conversion to idlers, quantum efficiency, and the commutator error. This is a full device example; reduce the cell count for a quick syntax check, but do not expect the same gain.</p><h2 id="Floquet-JTWPA" tabindex="-1">Floquet JTWPA <a class="header-anchor" href="#Floquet-JTWPA" aria-label="Permalink to &quot;Floquet JTWPA {#Floquet-JTWPA}&quot;">​</a></h2><p><a href="./recipes/floquet">Floquet JTWPA</a>. Taper the unit-cell parameters of a traveling-wave amplifier, then add dielectric loss. The second section reuses <code>floquetcircuit</code> from the first. Compare gain and normalized quantum efficiency, and check convergence of the harmonic truncations.</p><h2 id="Floquet-JTWPA-with-dissipation" tabindex="-1">Floquet JTWPA with dissipation <a class="header-anchor" href="#Floquet-JTWPA-with-dissipation" aria-label="Permalink to &quot;Floquet JTWPA with dissipation {#Floquet-JTWPA-with-dissipation}&quot;">​</a></h2><p><a href="/dev/recipes/floquet#Floquet-JTWPA-with-dissipation">Floquet JTWPA with dissipation</a>. Taper the unit-cell parameters of a traveling-wave amplifier, then add dielectric loss. The second section reuses <code>floquetcircuit</code> from the first. Compare gain and normalized quantum efficiency, and check convergence of the harmonic truncations.</p><h2 id="Impedance-engineered-JPA" tabindex="-1">Impedance-engineered JPA <a class="header-anchor" href="#Impedance-engineered-JPA" aria-label="Permalink to &quot;Impedance-engineered JPA {#Impedance-engineered-JPA}&quot;">​</a></h2><p><a href="./recipes/lesa">Impedance-engineered JPA</a>. Build an impedance-engineered JPA from nested snake and SQUID subcircuits. The signal and conjugate-idler curves are plotted in power units, so the idler conversion includes the absolute frequency ratio.</p><h2 id="Design-parameter-sensitivities" tabindex="-1">Design parameter sensitivities <a class="header-anchor" href="#Design-parameter-sensitivities" aria-label="Permalink to &quot;Design parameter sensitivities {#Design-parameter-sensitivities}&quot;">​</a></h2><p><a href="./recipes/sensitivities">Design parameter sensitivities</a>. Differentiate the JPA response with respect to its design parameters. The small executable example first checks a derivative against finite differences; the plotting recipe then expresses gain derivatives in dB per fractional parameter change.</p><h2 id="Sensitivity-to-frequency-dependent-scattering-parameters" tabindex="-1">Sensitivity to frequency dependent scattering parameters <a class="header-anchor" href="#Sensitivity-to-frequency-dependent-scattering-parameters" aria-label="Permalink to &quot;Sensitivity to frequency dependent scattering parameters {#Sensitivity-to-frequency-dependent-scattering-parameters}&quot;">​</a></h2><p><a href="./recipes/scattering-sensitivities">Sensitivity to frequency dependent scattering parameters</a>. Differentiate the reflection phase with respect to a matched line length. The analytic reference is the round-trip propagation phase. Block derivatives describe the data at one design point; rebuilding a block is required when its captured parameters change.</p><h2 id="Direct-current" tabindex="-1">Direct current <a class="header-anchor" href="#Direct-current" aria-label="Permalink to &quot;Direct current {#Direct-current}&quot;">​</a></h2><p><a href="./recipes/dc">Direct current</a>. Distinguish static flux from average voltage using a resistor carrying DC. The executable example checks Ohm&#39;s law without adding an artificial inductive path to ground.</p><h2 id="Transient-and-noise-examples" tabindex="-1">Transient and noise examples <a class="header-anchor" href="#Transient-and-noise-examples" aria-label="Permalink to &quot;Transient and noise examples {#Transient-and-noise-examples}&quot;">​</a></h2><ul><li><p><a href="./transient">Transient solve and response derivatives</a></p></li><li><p><a href="./recipes/transient-line">A Josephson line with ten pulsed signals</a></p></li><li><p><a href="./recipes/transient-wrspice">A JPA compared with WRspice in time</a></p></li><li><p><a href="./transientnoise">Vacuum and thermal noise of a passive two-port</a></p></li><li><p><a href="./scattering">Fit scattering data and simulate the result</a></p></li></ul>',29)])])}const u=a(n,[["render",s]]);export{d as __pageData,u as default};
